  });

  it("should parse additional tasks from Tasks section", () => {
    const plan = `
# Test Plan

## Specs

\`\`\`yaml
- title: Feature A
\`\`\`

## Tasks

derive_from_specs: true

\`\`\`yaml
- title: Manual Task 1
  priority: 1
  tags: [manual, testing]

- title: Manual Task 2
  priority: 2
\`\`\`
