        const ac = item.acceptance_criteria || [];

        output(ac, () => {
          console.log(
            chalk.bold(
              `Acceptance Criteria for: ${item.title} (@${item.slugs[0] || refIndex.shortUlid(item._ulid)})`,
            ),
