    .command("types")
    .description("Show item types and counts")
    .action(async () => {
      try {
        const ctx = await initContext();
        const { itemIndex } = await buildIndexes(ctx);

        const typeCounts = itemIndex.getTypeCounts();

        output(Object.fromEntries(typeCounts), () => {
