/**
 * Tests for comma-separated tag syntax
 *
 * AC: @comma-tag-syntax ac-1 - Parse comma-separated tags
 * AC: @comma-tag-syntax ac-2 - Parse mixed comma and space-separated tags
 * AC: @comma-tag-syntax ac-3 - Preserve existing space-separated behavior
 */

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { parseTagsArray } from "../src/cli/parse-utils.js";
import { cleanupTempDir, kspec, setupTempFixtures } from "./helpers/cli.js";

describe("parseTagsArray", () => {
  // AC: @comma-tag-syntax ac-1
  it("should parse comma-separated tags", () => {
    const result = parseTagsArray("cli,urgent");
    expect(result).toEqual(["cli", "urgent"]);
  });

  // AC: @comma-tag-syntax ac-2
  it("should parse mixed comma and space-separated tags", () => {
    const result = parseTagsArray(["cli,urgent", "api"]);
    expect(result).toEqual(["cli", "urgent", "api"]);
  });

  // AC: @comma-tag-syntax ac-3
  it("should preserve existing space-separated behavior", () => {
    const result = parseTagsArray(["cli", "urgent"]);
    expect(result).toEqual(["cli", "urgent"]);
  });

  it("should handle empty input", () => {
    expect(parseTagsArray(undefined)).toEqual([]);
    expect(parseTagsArray("")).toEqual([]);
    expect(parseTagsArray([])).toEqual([]);
  });

  it("should trim whitespace", () => {
    const result = parseTagsArray("cli , urgent , api");
    expect(result).toEqual(["cli", "urgent", "api"]);
  });

  it("should handle single tag", () => {
    const result = parseTagsArray("cli");
    expect(result).toEqual(["cli"]);
  });

  it("should filter out empty strings", () => {
    const result = parseTagsArray("cli,,urgent");
    expect(result).toEqual(["cli", "urgent"]);
  });
});

describe("CLI integration with comma-separated tags", () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @comma-tag-syntax ac-1
  it("should accept comma-separated tags in task add", async () => {
    const result = kspec(
      'task add --title "Test task" --tag cli,urgent',
      tempDir,
    );

    expect(result.exitCode).toBe(0);

    // Verify tags were added
    const getResult = kspec("tasks list --json", tempDir);
    const tasks = JSON.parse(getResult.stdout);
    expect(tasks[0].tags).toEqual(expect.arrayContaining(["cli", "urgent"]));
  });

  // AC: @comma-tag-syntax ac-2
  it("should accept mixed comma and space-separated tags in task add", async () => {
    const result = kspec(
      'task add --title "Test task" --tag cli,urgent api',
      tempDir,
    );

    expect(result.exitCode).toBe(0);

    const getResult = kspec("tasks list --json", tempDir);
    const tasks = JSON.parse(getResult.stdout);
    expect(tasks[0].tags).toEqual(
      expect.arrayContaining(["cli", "urgent", "api"]),
    );
  });

  // AC: @comma-tag-syntax ac-3
  it("should preserve existing --tag --tag behavior", async () => {
    const result = kspec(
      'task add --title "Test task" --tag cli --tag urgent',
      tempDir,
    );

    expect(result.exitCode).toBe(0);

    const getResult = kspec("tasks list --json", tempDir);
    const tasks = JSON.parse(getResult.stdout);
    expect(tasks[0].tags).toEqual(expect.arrayContaining(["cli", "urgent"]));
  });

  it("should work with inbox add", async () => {
    const result = kspec('inbox add "Test item" --tag cli,urgent', tempDir);

    expect(result.exitCode).toBe(0);

    const listResult = kspec("inbox list --json", tempDir);
    const items = JSON.parse(listResult.stdout);
    expect(items[0].tags).toEqual(expect.arrayContaining(["cli", "urgent"]));
  });

  it("should work with item add under module", async () => {
    // First create a module
    kspec('module add test-module --title "Test Module" --slug test-module', tempDir);

    // Add item with comma-separated tags
    const result = kspec(
      'item add --under test-module --title "Test item" --tag cli,urgent',
      tempDir,
    );

    expect(result.exitCode).toBe(0);

    const listResult = kspec("item list --json", tempDir);
    const items = JSON.parse(listResult.stdout);
    const testItem = items.find((i: any) => i.title === "Test item");
    expect(testItem.tags).toEqual(expect.arrayContaining(["cli", "urgent"]));
  });

  it("should work with task set", async () => {
    // Create task
    kspec('task add --title "Test task"', tempDir);

    // Get task ref
    const listResult = kspec("tasks list --json", tempDir);
    const tasks = JSON.parse(listResult.stdout);
    const taskRef = `@${tasks[0].slugs[0] || tasks[0]._ulid.slice(0, 8)}`;

    // Set tags with comma-separated syntax
    const result = kspec(`task set ${taskRef} --tag cli,urgent`, tempDir);

    expect(result.exitCode).toBe(0);

    const getResult = kspec(`task get ${taskRef} --json`, tempDir);
    const task = JSON.parse(getResult.stdout);
    expect(task.tags).toEqual(expect.arrayContaining(["cli", "urgent"]));
  });
});
